func (l *LLM) Close() {
	l.closeMu.Lock()
	defer l.closeMu.Unlock()
	if l.sched != nil {
		l.sched.close()
		l.sched = nil
	}
	if l.g != nil {
		_ = l.opt.Device.Do(func(*vk.Device) error {
