ins("llm/gpu_attn.go", "// NBlocks is the indexer's block count:", '''// FrontierRow reads, from every layer, the pooled indexer row a checkpoint at
// `past` needs, and RestoreFrontier writes it back over the blocks a later
// run completed (CONCURRENCY.md C4).
//
// **It is one row, not a table, because every block from past/ratio on holds
// the same one.** A fresh sequence writes the whole table and a block that
// does not exist yet pools cell 0 `ratio` times (llm_attn_idx.comp); after
// that a run rewrites only the blocks it completes. So at any position the
// first incomplete block and every block after it hold token 0's pooled key,
// and going back to `past` means putting that row back over
// [past/ratio, frontier/ratio): the blocks the abandoned continuation
// finished. The KV cells and raw keys need nothing: a cell at or past `past`
// is masked out of every score until it is rewritten.
func (g *AttnGPU) FrontierRow(past int) []uint16 {
	blk, n := past/g.cfg.Ratio, g.cfg.IdxDim
	out := make([]uint16, 0, len(g.layers)*n)
	for l := range g.layers {
		out = append(out, g.ibuf.ReadUint16At(int(g.hIdxK)+l*g.idxKStride+blk*n, n)...)
	}
	return out
}

func (g *AttnGPU) RestoreFrontier(past, frontier int, row []uint16) error {
	n := g.cfg.IdxDim
	if len(row) != len(g.layers)*n {
		return fmt.Errorf("llm: a %d-value pooled row against %d layers of %d", len(row), len(g.layers), n)
	}
	lo, hi := past/g.cfg.Ratio, min(frontier/g.cfg.Ratio, g.NBlocks())
	for l := range g.layers {
		for b := lo; b < hi; b++ {
			g.ibuf.WriteUint16At(int(g.hIdxK)+l*g.idxKStride+b*n, row[l*n:(l+1)*n])
		}
	}
	return nil
}

