148					t.Fatal(err)
149				}
150			}
151			if skip != noDeltaNet {
152				if err := g.dn.RestoreCarried(c.dn); err != nil {
153					t.Fatal(err)
154				}
155			}
156			if skip != noPLE {
157				if err := g.ple.RestoreCarried(c.ple); err != nil {
158					t.Fatal(err)
159				}
160			}
161			if err := g.rewindPosition(c.past, c.past); err != nil {
162				t.Fatal(err)
163			}
164		}
165	
166		var ck *Checkpoint
167		run := func(skip part) [][]float32 {
168			use(1)
169			feed(pre, true)
170			var err error
171			if ck, err = g.Checkpoint(ck); err != nil {
172				t.Fatal(err)
173			}
174			// Somewhere else first: the abandoned continuation, then the other
175			// slot's conversation, then back.
176			feed(other, false)
177			for range steps {
178				if _, _, err := g.Extend([]int32{toks[0]}); err != nil {
179					t.Fatal(err)
180				}
181			}
182			use(0)
183			feed(other, true)
184			use(1)
185			restore(ck, skip)
