187				t.Fatalf("restored to position %d, want %d", g.Past(), prefix)
188			}
189			_, rows := finish(toks)
190			return rows
191		}
192	
193		firstDiff := func(got [][]float32) string {
194			for r := range want {
195				for j := range want[r] {
196					if got[r][j] != want[r][j] {
197						return fmt.Sprintf("row %d logit %d: %g against %g", r, j, got[r][j], want[r][j])
198					}
199				}
200			}
201			return ""
202		}
203	
204		if d := firstDiff(run(all3)); d != "" {
205			t.Fatalf("restoring the checkpoint is not the prefill: %s", d)
206		}
207		t.Logf("checkpoint at %d of %d cells, %d-token detour past it and %d steps, restored in slot 1 with "+
208			"slot 0 run between: %d logit rows bit-identical to prefix + tail", prefix, nKV, len(other), steps, len(want))
209	
210		for _, c := range []struct {
211			name string
212			skip part
213		}{
214			{"the deltanet state and rings", noDeltaNet},
215			{"the ple ring", noPLE},
216			{"the pooled indexer blocks", noPooled},
217		} {
218			d := firstDiff(run(c.skip))
219			if d == "" {
220				t.Errorf("control: a restore without %s gives the same logits, so the gate cannot see it", c.name)
221				continue
222			}
223			t.Logf("control, without %s: moves at %s", c.name, d)
224		}
225	
226		// Restore refuses a slot that no longer holds the checkpoint's tokens:
227		// the cells below it are some other conversation's now.
228		use(1)
229		feed(other, true)
230		if err := g.Restore(ck); err == nil {
231			t.Error("Restore accepted a checkpoint after the slot was re-run from token zero with other tokens")
232		}
233	}

