	reused  int
	restore bool
	// mark is where to take the slot's checkpoint during the prefill, as a
	// position in the prompt, or 0 for nowhere.
	mark int''')

rep('''type llmUnit struct {
	job   *llmJob
	ids   []int32
	fresh bool''','''type llmUnit struct {
	job   *llmJob
	ids   []int32
	fresh bool
	// restore takes the slot back to its checkpoint before the first chunk.
	restore bool''')

rep('''func (s *llmSched) acquire(ctx context.Context, class llmClass, ids []int32) (*llmJob, error) {''',
'''func (s *llmSched) acquire(ctx context.Context, class llmClass, ids []int32, mark int) (*llmJob, error) {''')
rep('''	j := &llmJob{ctx: ctx, class: class, slot: -1, arrival: s.arrival, prompt: ids,
		granted: make(chan struct{})}''','''	j := &llmJob{ctx: ctx, class: class, slot: -1, arrival: s.arrival, prompt: ids, mark: mark,
		granted: make(chan struct{})}''')

rep('''// freeSlot picks the slot for a job of this class: the one already holding
// the longest usable prefix of its prompt, else the least recently used.''','''// freeSlot picks the slot for a job of this class: the one that saves the
// most of its prompt (a held prefix or a checkpoint), else the least recently
// used.''')
rep('''		reuse := usablePrefix(sl.held, prompt)
		if best < 0''','''		reuse, _ := sl.reuse(prompt)
		if best < 0''')
rep('''	j.reused = usablePrefix(s.slots[slot].held, j.prompt)''','''	j.reused, j.restore = s.slots[slot].reuse(j.prompt)''')

rep('''	u := &llmUnit{job: j, ids: ids, fresh: fresh, done: make(chan struct{})}
	s.mu.Lock()''','''	u := &llmUnit{job: j, ids: ids, fresh: fresh, done: make(chan struct{})}
	s.mu.Lock()
	u.restore, j.restore = j.restore, false''')

rep('''		chunk, next := u.ids[:n], u.ids[n:min(len(u.ids), 2*n)]
		slot, fresh := u.job.slot, u.fresh
		s.running = u
		s.mu.Unlock()''','''		slot, fresh, restore := u.job.slot, u.fresh, u.restore
		sl := &s.slots[slot]
		var ck *llm.Checkpoint
		pos := len(sl.held)
		switch {
		case fresh:
			pos = 0
		case restore:
			ck = sl.ckpt
			pos = ck.Past()
		}
