		mark := u.job.mark
		if mark > pos && mark < pos+n {
			n = mark - pos
		}
		take := mark > 0 && pos+n == mark
		chunk, next := u.ids[:n], u.ids[n:min(len(u.ids), 2*n)]
		keep := sl.ckpt
		s.running = u
		s.mu.Unlock()''')

rep('''				var err error
				if fresh {
					logits, _, err = s.g.Forward(chunk)
				} else {
					logits, _, err = s.g.Extend(chunk)
				}
				return err
			})''','''				if restore {
					if err := s.g.Restore(ck); err != nil {
						return err
					}
				}
