		case fresh:
			sl.held = append(sl.held[:0], chunk...)
		case restore:
			sl.held = append(sl.held[:ck.Past()], chunk...)
		default:
			sl.held = append(sl.held, chunk...)
		}
		if err == nil && take {
			sl.ckpt = keep
		}
		u.busy += took
		u.job.served += took
		u.ids, u.fresh, u.restore = u.ids[n:], false, false''')

rep('''	"fmt"
	"sync"''','''	"fmt"
	"log"
	"sync"''')
open(p,"w").write(s)
EOF
