		// strided by the layer that filled it (L7a).
		KOff:    g.hK + uint32(layer*g.kvStride),
		VOff:    g.hV + uint32(layer*g.kvStride),
		IdxKOff: g.hIdxK + uint32(layer*g.idxKStride),
