	}
	if g.dn != nil {
		g.dn.rec = g.rec
	}
	if g.attn != nil {
		g.attn.rec = g.rec
	}
	if g.moe != nil {
		g.moe.rec = g.rec
	}
	if g.head != nil {
		g.head.rec = g.rec
	}
}

