	// one a block (L7d).
	if g.rec.add(ownDN, kinds, d) {
		return nil
	}
	if _, err := vk.DispatchMultiTimed(d, 1, 1, true); err != nil {
		return fmt.Errorf("llm: deltanet, %d dispatches (%v): %w", len(d), kinds, err)
	}
	return nil
}

