	outPipe := string(g.outGemm)
	if g.quant() {
		outPipe = bankPipe(g.bank, g.outGemm)
	}
	if ks := gemvSlabs(g.outGemv); ks > 0 {
		out.ResOff = g.aPart
		add(gemvBankPipeRows(g.outGemv, g.bank, g.rows), "out", uint32(ks), uint32(c.NEmbd/16), out)
