	if err := g.move.Move(g.head.InPort(), g.hc.MixedPort(), n); err != nil {
		return nil, nil, err
	}
	t0 = g.blk(&g.Stats.Move, t0)
	if err := g.head.Run(); err != nil {
		return nil, nil, err
	}
