p="llm/gpu_qsa4k_test.go"; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a[:60]; s=s.replace(a,b)
rep('''	// share, the control, leaves the last slot on slot 0's pipelines — whose
	// descriptor sets name slot 0's buffers — after switching to it.
	share := false
	run :=''','''	run :=''')
